-- Adds 37 additional starter drills as scope:"library" seed templates
-- (sourced from US Soccer/US Youth Soccer/The FA/AYSO U8 curricula),
-- deduplicated against the original 20 by name and by mechanic where a
-- different name described an effectively identical drill. These rows are
-- never queried directly by the client - they exist only as the template
-- seedTeamDrillsFromLibrary() copies from at team creation.
INSERT INTO "Drill" ("id", "teamId", "name", "slug", "category", "focusAreas", "defaultMinutes", "minMinutes", "maxMinutes", "minPlayers", "maxPlayers", "equipment", "setup", "instructions", "coachingPoints", "progressions", "ageNotes", "scope", "updatedAt") VALUES ('lib-free-dribble', NULL, 'Free Dribble', 'free-dribble', 'warmup', ARRAY['dribbling', 'spatial_awareness']::TEXT[], 5, 4, 7, 4, 12, ARRAY['One size-3 ball per player', 'Cones']::TEXT[], 'Mark a 20x25-yard grid with cones (shrink to 15x20 for fewer players). Every player has a ball inside the grid.', 'All players dribble their ball freely inside the grid at the same time. On the coach''s call, players change direction or perform a move and accelerate into open space. Players keep dribbling until time is called.', ARRAY['Head up, find a space.', 'Little touches.', 'Show me a new move.', 'Speed up when it''s open.']::TEXT[], ARRAY['(easier) Enlarge the grid', '(harder) Coach moves through as a passive defender', '(harder) Players dribble toward each other, make a move, and accelerate away']::TEXT[], '', 'library', CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Drill" ("id", "teamId", "name", "slug", "category", "focusAreas", "defaultMinutes", "minMinutes", "maxMinutes", "minPlayers", "maxPlayers", "equipment", "setup", "instructions", "coachingPoints", "progressions", "ageNotes", "scope", "updatedAt") VALUES ('lib-freeze-tag-with-balls', NULL, 'Freeze Tag with Balls', 'freeze-tag-with-balls', 'warmup', ARRAY['dribbling', 'spatial_awareness']::TEXT[], 5, 4, 7, 6, 12, ARRAY['One ball per player', 'Cones']::TEXT[], 'Mark a 20x20-yard grid. Every player has a ball; one or two players (or the coach) are taggers.', 'Taggers try to tag dribbling players with their hand. When tagged, a player stops, stands with legs apart and holds their ball above their head. A frozen player is freed when another player passes a ball between their legs. Play runs for a set time, then new taggers are chosen.', ARRAY['Keep it close so you can turn away.', 'Look for a friend to unfreeze.', 'Change speed.']::TEXT[], ARRAY['(harder) Add a tagger', '(easier) Remove a tagger', '(harder) Unfreezing requires the freed player to then perform a move']::TEXT[], '', 'library', CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Drill" ("id", "teamId", "name", "slug", "category", "focusAreas", "defaultMinutes", "minMinutes", "maxMinutes", "minPlayers", "maxPlayers", "equipment", "setup", "instructions", "coachingPoints", "progressions", "ageNotes", "scope", "updatedAt") VALUES ('lib-hit-the-dirt', NULL, 'Hit the Dirt', 'hit-the-dirt', 'warmup', ARRAY['dribbling', 'spatial_awareness', 'fitness_disguised']::TEXT[], 4, 4, 6, 4, 12, ARRAY['One ball per player', 'Cones']::TEXT[], 'Mark a 15x20-yard grid. Every player has a ball.', 'Players dribble around the grid. When the coach calls "hit the dirt," each player stops the ball and touches their chest to the ground. When the coach calls "up," players jump up and resume dribbling. Repeat with varied calls.', ARRAY['Quick down, quick up.', 'Stop the ball first.', 'Find space when you get up.']::TEXT[], ARRAY['(harder) Add sit-on-the-ball or turn calls', '(harder) Last one down does a silly dance', '(easier) Slow the calls']::TEXT[], '', 'library', CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Drill" ("id", "teamId", "name", "slug", "category", "focusAreas", "defaultMinutes", "minMinutes", "maxMinutes", "minPlayers", "maxPlayers", "equipment", "setup", "instructions", "coachingPoints", "progressions", "ageNotes", "scope", "updatedAt") VALUES ('lib-math-dribbling', NULL, 'Math Dribbling', 'math-dribbling', 'warmup', ARRAY['dribbling', 'spatial_awareness']::TEXT[], 5, 4, 6, 6, 12, ARRAY['One ball per player', 'Cones']::TEXT[], 'Mark a 15x20-yard grid. Every player has a ball.', 'Players dribble around the grid. The coach calls a number; players quickly form groups containing that many players while keeping their balls with them. Any players who cannot form a complete group do a quick silly action, then all players spread out and dribble again for the next call. Coach may call sums like "1+1."', ARRAY['Keep dribbling while you find your group.', 'Head up to find friends.', 'Quick feet.']::TEXT[], ARRAY['(harder) Call arithmetic problems', '(harder) Groups must make a pass before the count is complete', '(easier) Call only simple numbers']::TEXT[], '', 'library', CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Drill" ("id", "teamId", "name", "slug", "category", "focusAreas", "defaultMinutes", "minMinutes", "maxMinutes", "minPlayers", "maxPlayers", "equipment", "setup", "instructions", "coachingPoints", "progressions", "ageNotes", "scope", "updatedAt") VALUES ('lib-pirates-of-the-caribbean', NULL, 'Pirates of the Caribbean', 'pirates-of-the-caribbean', 'warmup', ARRAY['dribbling', 'first_touch', 'spatial_awareness']::TEXT[], 5, 4, 6, 6, 12, ARRAY['One ball per player', 'Cones']::TEXT[], 'Mark a rectangular "ship" roughly 25x20 yards. Name the four sides Bow (front), Stern (back), Port (left) and Starboard (right).', 'Players dribble around inside the ship. When the coach calls a side name, all players dribble to that side. On skill calls players perform an action: "scrub the deck" = sole rolls, "climb the rigging" = toe-taps, "captain on board" = foot on ball and salute, "cannonball" = lie down quickly. Play continues with new calls.', ARRAY['Head up, keep the ball close.', 'Listen for the call.', 'Turn quickly.']::TEXT[], ARRAY['(harder) Add more skill calls', '(harder) Last player to each side does a small forfeit', '(easier) Call sides more slowly']::TEXT[], '', 'library', CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Drill" ("id", "teamId", "name", "slug", "category", "focusAreas", "defaultMinutes", "minMinutes", "maxMinutes", "minPlayers", "maxPlayers", "equipment", "setup", "instructions", "coachingPoints", "progressions", "ageNotes", "scope", "updatedAt") VALUES ('lib-tiger-tails', NULL, 'Tiger Tails', 'tiger-tails', 'warmup', ARRAY['dribbling', 'spatial_awareness', 'fitness_disguised']::TEXT[], 5, 4, 6, 6, 12, ARRAY['One pinnie per player (as a tail)', 'Optional: one ball per player']::TEXT[], 'Mark a 30x20-yard area. Each player tucks a pinnie into the back of their shorts so it is visible.', 'On "go," players run around the area trying to pull other players'' tails while protecting their own. A pulled tail is added to the puller''s collection. A tail dropped on the ground can be picked up by the first player to reach it. Players cannot hold their own tail. After a set time, the player with the most tails wins and tails are redistributed.', ARRAY['Turn and protect.', 'Sprint into space.', 'Watch behind you.']::TEXT[], ARRAY['(harder) Every player also dribbles a ball', '(harder) A player whose tail is taken dribbles a lap of the outside before re-entering', '(easier) Shorten the round']::TEXT[], '', 'library', CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Drill" ("id", "teamId", "name", "slug", "category", "focusAreas", "defaultMinutes", "minMinutes", "maxMinutes", "minPlayers", "maxPlayers", "equipment", "setup", "instructions", "coachingPoints", "progressions", "ageNotes", "scope", "updatedAt") VALUES ('lib-spiderweb-tig', NULL, 'Spiderweb Tig', 'spiderweb-tig', 'warmup', ARRAY['dribbling', 'spatial_awareness', 'fitness_disguised']::TEXT[], 5, 4, 6, 6, 12, ARRAY['Cones', 'Two pinnies']::TEXT[], 'Mark a 30x30-yard area. Choose two taggers and give each a bib.', 'The two taggers each hold a bib and try to throw it so it touches another player; each hit scores the tagger a point. All other players dodge around the area to avoid being hit. After a hit, the tagger retrieves the bib and continues. Rotate taggers after a set time.', ARRAY['Change direction fast.', 'Watch both taggers.', 'Use the whole space.']::TEXT[], ARRAY['(easier) Enlarge the area', '(harder) Shrink the area', '(harder) Every dodger dribbles a ball']::TEXT[], '', 'library', CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Drill" ("id", "teamId", "name", "slug", "category", "focusAreas", "defaultMinutes", "minMinutes", "maxMinutes", "minPlayers", "maxPlayers", "equipment", "setup", "instructions", "coachingPoints", "progressions", "ageNotes", "scope", "updatedAt") VALUES ('lib-shadow-dribble', NULL, 'Shadow Dribble', 'shadow-dribble', 'warmup', ARRAY['dribbling', 'spatial_awareness']::TEXT[], 5, 4, 6, 4, 12, ARRAY['One ball per player', 'Cones']::TEXT[], 'Mark a 20x25-yard grid. Pair players; both partners have a ball.', 'One partner is the leader and dribbles anywhere in the grid; the other is the shadow and dribbles to stay close behind, copying the leader''s path. On the coach''s call, the roles swap. Play continues alternating leaders.', ARRAY['Copy the leader.', 'Keep your ball close so you can turn.', 'Eyes up.']::TEXT[], ARRAY['(harder) Leader must perform a move that the shadow copies', '(harder) Weaker foot only', '(harder) After a 2-second head start the shadow tries to tag the leader, then roles reverse']::TEXT[], '', 'library', CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Drill" ("id", "teamId", "name", "slug", "category", "focusAreas", "defaultMinutes", "minMinutes", "maxMinutes", "minPlayers", "maxPlayers", "equipment", "setup", "instructions", "coachingPoints", "progressions", "ageNotes", "scope", "updatedAt") VALUES ('lib-gate-dribbling-with-bandits', NULL, 'Gate Dribbling with Bandits', 'gate-dribbling-with-bandits', 'technical', ARRAY['dribbling', 'defending']::TEXT[], 6, 4, 8, 6, 12, ARRAY['One ball per dribbler', 'Cones']::TEXT[], 'Mark a 15x20-yard grid with many two-cone gates. All but 2 players have a ball; the 2 without are bandits.', 'Dribblers score a point for each gate they dribble through in the round (60-90 seconds). Bandits try to steal a ball; once a bandit wins a ball they become a dribbler and try to score, while the player who lost the ball becomes a bandit. A ball kicked out of the grid stays out. Players keep their points at the end of the round.', ARRAY['Protect the ball with your body.', 'Change direction away from the bandit.', 'Accelerate through the gate.']::TEXT[], ARRAY['(easier) Fewer bandits', '(harder) Shrink the grid', '(harder) Bandits work as a pair']::TEXT[], '', 'library', CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Drill" ("id", "teamId", "name", "slug", "category", "focusAreas", "defaultMinutes", "minMinutes", "maxMinutes", "minPlayers", "maxPlayers", "equipment", "setup", "instructions", "coachingPoints", "progressions", "ageNotes", "scope", "updatedAt") VALUES ('lib-steal-shield', NULL, 'Steal-Shield', 'steal-shield', 'technical', ARRAY['dribbling', 'defending', 'first_touch']::TEXT[], 6, 4, 8, 4, 12, ARRAY['One ball per pair', 'Cones']::TEXT[], 'Mark a 20x25-yard area or small individual squares. Pair the players; one partner starts with the ball.', 'On the coach''s command the partner without the ball tries to steal it while the ball-holder shields and keeps possession. Play 30-45 second rounds; whoever has the ball at the end scores a point. If the ball goes out, a player quickly brings it back in. Partners then switch who starts with the ball.', ARRAY['Body between the ball and the defender.', 'Arm out to feel them.', 'Knees bent, turn away.']::TEXT[], ARRAY['(harder) Shrink the space', '(harder) Allow the stealer to score by dribbling the won ball to a line', '(easier) Lengthen the shield time']::TEXT[], '', 'library', CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Drill" ("id", "teamId", "name", "slug", "category", "focusAreas", "defaultMinutes", "minMinutes", "maxMinutes", "minPlayers", "maxPlayers", "equipment", "setup", "instructions", "coachingPoints", "progressions", "ageNotes", "scope", "updatedAt") VALUES ('lib-ball-tag', NULL, 'Ball Tag', 'ball-tag', 'technical', ARRAY['passing', 'dribbling']::TEXT[], 5, 4, 7, 6, 12, ARRAY['One ball per player', 'Cones']::TEXT[], 'Mark a 15x20-yard grid. Every player has a ball; choose 2-3 taggers.', 'Taggers dribble and try to strike another player''s feet or ball with their own ball, using a pass rather than a throw. Each hit scores the tagger a point; taggers keep their own count. Non-taggers dribble and shield to avoid being hit. Choose new taggers each round until everyone has had a turn.', ARRAY['Pass to hit, don''t kick wildly.', 'Get close before you pass.', 'Shield your ball.']::TEXT[], ARRAY['(harder) Taggers may only hit the ball, not feet', '(harder) Shrink the grid', '(easier) Fewer taggers']::TEXT[], '', 'library', CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Drill" ("id", "teamId", "name", "slug", "category", "focusAreas", "defaultMinutes", "minMinutes", "maxMinutes", "minPlayers", "maxPlayers", "equipment", "setup", "instructions", "coachingPoints", "progressions", "ageNotes", "scope", "updatedAt") VALUES ('lib-paint-the-field', NULL, 'Paint the Field', 'paint-the-field', 'technical', ARRAY['passing', 'first_touch']::TEXT[], 6, 4, 8, 4, 12, ARRAY['One ball per pair', 'Cones']::TEXT[], 'Mark a 20x25-yard grid. Pair players; each pair shares one ball.', 'Pairs pass the ball back and forth to each other while moving so the ball rolls over as much of the grid as possible. Pairs keep moving and passing for the set time.', ARRAY['Pass to your partner''s feet.', 'Move to a new space after you pass.', 'Inside of the foot.']::TEXT[], ARRAY['(harder) Weaker foot only', '(harder) Limit to two touches', '(easier) Allow players to stop the ball before passing']::TEXT[], '', 'library', CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Drill" ("id", "teamId", "name", "slug", "category", "focusAreas", "defaultMinutes", "minMinutes", "maxMinutes", "minPlayers", "maxPlayers", "equipment", "setup", "instructions", "coachingPoints", "progressions", "ageNotes", "scope", "updatedAt") VALUES ('lib-gate-passing', NULL, 'Gate Passing', 'gate-passing', 'technical', ARRAY['passing', 'first_touch']::TEXT[], 6, 4, 8, 4, 12, ARRAY['One ball per pair', 'Cones (2 per gate)']::TEXT[], 'Mark a 20x25-yard grid with many two-cone gates about 2 yards wide. Pair players; each pair shares one ball.', 'Partners pass the ball to each other through a gate to score one point, then move to a different gate and repeat. Pairs count points over a set time and try to beat their score in the next round.', ARRAY['Look at your partner before you pass.', 'Firm, accurate pass.', 'Move to the next gate together.']::TEXT[], ARRAY['(harder) Inside vs. outside of foot', '(harder) One-touch through the gate', '(easier) Widen gates']::TEXT[], '', 'library', CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Drill" ("id", "teamId", "name", "slug", "category", "focusAreas", "defaultMinutes", "minMinutes", "maxMinutes", "minPlayers", "maxPlayers", "equipment", "setup", "instructions", "coachingPoints", "progressions", "ageNotes", "scope", "updatedAt") VALUES ('lib-soccer-horseshoes', NULL, 'Soccer Horseshoes', 'soccer-horseshoes', 'technical', ARRAY['passing', 'shooting']::TEXT[], 6, 4, 8, 4, 12, ARRAY['One ball per pair', 'Tall cones']::TEXT[], 'In a 15x20-yard area, pair players standing about 5 yards apart on opposite sides of a center cone that has a ball balanced on top.', 'One player passes their ball to try to knock the ball off the center cone; a successful knock scores one point. The opponent resets the ball on the cone, then takes their turn. First to 3 points, then players find a new opponent.', ARRAY['Plant foot next to the ball.', 'Eyes on the target.', 'Lock your ankle.']::TEXT[], ARRAY['(harder) Move players farther apart', '(harder) Require one-touch strikes', '(easier) Move closer']::TEXT[], '', 'library', CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Drill" ("id", "teamId", "name", "slug", "category", "focusAreas", "defaultMinutes", "minMinutes", "maxMinutes", "minPlayers", "maxPlayers", "equipment", "setup", "instructions", "coachingPoints", "progressions", "ageNotes", "scope", "updatedAt") VALUES ('lib-cops-and-robbers', NULL, 'Cops and Robbers', 'cops-and-robbers', 'technical', ARRAY['passing', 'shooting']::TEXT[], 6, 4, 8, 6, 12, ARRAY['Balls', '8-10 tall cones']::TEXT[], 'In a 20x25-yard grid, stand up 8-10 tall cones. Choose 2-3 players as cops without balls; the rest are robbers with balls.', 'Robbers strike their balls to knock down the cones. Cops, who have no ball, run around standing the cones back up. Play for a set time or until all cones are down, then swap cops and robbers.', ARRAY['Aim before you strike.', 'Get close for a sure hit.', 'Follow your shot.']::TEXT[], ARRAY['(harder) More cops', '(harder) Robbers must strike from outside a marked line', '(easier) More robbers']::TEXT[], '', 'library', CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Drill" ("id", "teamId", "name", "slug", "category", "focusAreas", "defaultMinutes", "minMinutes", "maxMinutes", "minPlayers", "maxPlayers", "equipment", "setup", "instructions", "coachingPoints", "progressions", "ageNotes", "scope", "updatedAt") VALUES ('lib-pass-or-dribble-between-boxes', NULL, 'Pass or Dribble Between Boxes', 'pass-or-dribble-between-boxes', 'technical', ARRAY['passing', 'dribbling', 'first_touch']::TEXT[], 6, 4, 8, 8, 12, ARRAY['Cones', 'One ball per group of 4']::TEXT[], 'Mark two 10x10-yard boxes about 5 yards apart. Put a group of 4 players with one ball in each box.', 'On the coach''s command, each group passes their ball among their teammates inside their box. When the coach calls "switch," both groups dribble or pass their ball across to swap boxes and continue passing in the new space. Groups may race to reach a target number of passes first.', ARRAY['Head up before you pass.', 'Move after you pass.', 'Call for the ball.']::TEXT[], ARRAY['(harder) Players must pass rather than dribble between boxes', '(harder) Limit touches', '(easier) Allow dribbling between boxes']::TEXT[], '', 'library', CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Drill" ("id", "teamId", "name", "slug", "category", "focusAreas", "defaultMinutes", "minMinutes", "maxMinutes", "minPlayers", "maxPlayers", "equipment", "setup", "instructions", "coachingPoints", "progressions", "ageNotes", "scope", "updatedAt") VALUES ('lib-the-triangle', NULL, 'The Triangle', 'the-triangle', 'technical', ARRAY['first_touch', 'passing']::TEXT[], 6, 4, 8, 4, 12, ARRAY['One ball per pair', '3 cones per pair']::TEXT[], 'For each pair, make a small triangle of three cones about 3-5 steps per side. Partners stand on opposite sides of the triangle sharing one ball.', 'Players pass the ball through the triangle to their partner, who redirects it with their first touch around a cone and back through the triangle without hitting the cones. Each clean sequence scores a point.', ARRAY['First touch out of your feet.', 'Redirect, keep it moving.', 'Inside or outside of the foot.']::TEXT[], ARRAY['(harder) One-touch redirect', '(harder) Smaller triangle', '(easier) Allow extra touches']::TEXT[], '', 'library', CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Drill" ("id", "teamId", "name", "slug", "category", "focusAreas", "defaultMinutes", "minMinutes", "maxMinutes", "minPlayers", "maxPlayers", "equipment", "setup", "instructions", "coachingPoints", "progressions", "ageNotes", "scope", "updatedAt") VALUES ('lib-receiving-triangles', NULL, 'Receiving Triangles', 'receiving-triangles', 'technical', ARRAY['first_touch', 'passing', 'spatial_awareness']::TEXT[], 6, 4, 8, 6, 12, ARRAY['Cones (3 per triangle)', 'Balls for dribblers']::TEXT[], 'In a 20x20-yard grid, build several small three-cone triangles. Place one player inside each triangle; the rest dribble balls around the grid.', 'A dribbling player passes their ball into a triangle player, then takes that player''s place inside the triangle. The player who received the pass dribbles out and looks to feed a different triangle. Play continues so players constantly rotate in and out of triangles.', ARRAY['Look up to find a triangle.', 'Pass to feet.', 'Swap quickly.']::TEXT[], ARRAY['(harder) Big triangles require an inside-foot first touch, small triangles an outside-foot touch', '(harder) One-touch pass in', '(easier) Larger triangles']::TEXT[], '', 'library', CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Drill" ("id", "teamId", "name", "slug", "category", "focusAreas", "defaultMinutes", "minMinutes", "maxMinutes", "minPlayers", "maxPlayers", "equipment", "setup", "instructions", "coachingPoints", "progressions", "ageNotes", "scope", "updatedAt") VALUES ('lib-pass-and-move-around-a-cone', NULL, 'Pass and Move Around a Cone', 'pass-and-move-around-a-cone', 'technical', ARRAY['passing', 'first_touch']::TEXT[], 5, 4, 7, 4, 12, ARRAY['One ball per pair', 'One cone per pair']::TEXT[], 'Pair players standing 5-10 yards apart with a single cone placed midway between them. Each pair has one ball.', 'Partners pass the ball to each other past the cone; the receiver controls the ball to one side of the cone with their first touch and passes it back from the other side. Players continue passing back and forth, alternating the receiving and passing sides.', ARRAY['Plant foot points at your partner.', 'First touch across your body.', 'Firm pass.']::TEXT[], ARRAY['(harder) Alternate inside and outside foot combinations', '(harder) Two-touch limit', '(easier) Remove the cone']::TEXT[], '', 'library', CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Drill" ("id", "teamId", "name", "slug", "category", "focusAreas", "defaultMinutes", "minMinutes", "maxMinutes", "minPlayers", "maxPlayers", "equipment", "setup", "instructions", "coachingPoints", "progressions", "ageNotes", "scope", "updatedAt") VALUES ('lib-toss-and-catch-juggling', NULL, 'Toss and Catch Juggling', 'toss-and-catch-juggling', 'technical', ARRAY['first_touch']::TEXT[], 4, 4, 6, 4, 12, ARRAY['One ball per player']::TEXT[], 'Players spread out in an open area, each holding a ball.', 'Each player drops their ball from their hands and tries to kick it back up to catch it, using feet and thighs. Players count how many touches they make before the ball hits the ground. Repeat and try to beat the count.', ARRAY['Toes up, soft touch.', 'Under the ball.', 'Count out loud.']::TEXT[], ARRAY['(harder) Two touches before catch, then three', '(harder) Alternate feet and thighs', '(easier) One bounce allowed between touches']::TEXT[], '', 'library', CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Drill" ("id", "teamId", "name", "slug", "category", "focusAreas", "defaultMinutes", "minMinutes", "maxMinutes", "minPlayers", "maxPlayers", "equipment", "setup", "instructions", "coachingPoints", "progressions", "ageNotes", "scope", "updatedAt") VALUES ('lib-funny-turns', NULL, 'Funny Turns', 'funny-turns', 'technical', ARRAY['dribbling', 'first_touch']::TEXT[], 5, 4, 7, 5, 12, ARRAY['One ball per player', 'Cones']::TEXT[], 'Mark a circle about 10 yards across with a small cone diamond in the center. Players start in the diamond, each with a ball.', 'One player dribbles to an outer cone and shows any turn they like; everyone watches, then gets about a minute to practice that turn. Players then work around the circle performing the turn and returning through the center each time. A new player demonstrates the next turn so everyone gets a turn to lead.', ARRAY['Keep the ball close in the turn.', 'Try it both feet.', 'Be inventive.']::TEXT[], ARRAY['(harder) Add 1-2 defenders in the circle to avoid', '(harder) Require a specific named turn', '(easier) Allow larger touches']::TEXT[], '', 'library', CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Drill" ("id", "teamId", "name", "slug", "category", "focusAreas", "defaultMinutes", "minMinutes", "maxMinutes", "minPlayers", "maxPlayers", "equipment", "setup", "instructions", "coachingPoints", "progressions", "ageNotes", "scope", "updatedAt") VALUES ('lib-moving-goal', NULL, 'Moving Goal', 'moving-goal', 'technical', ARRAY['passing', 'shooting', 'first_touch']::TEXT[], 5, 4, 7, 6, 12, ARRAY['One ball per pair', 'Two pinnies or pool noodles (held as a goal)']::TEXT[], 'In an open area, two adults or two players hold a pinnie or noodle between them to form a moving goal. Pair the players; each pair has one ball.', 'The two goal-holders walk around the area. Each pair passes and moves together and tries to pass their ball through the moving goal to score. After scoring, the pair spreads out and looks to score again as the goal keeps moving.', ARRAY['Move apart so you have an angle.', 'Pass, don''t blast.', 'Follow the goal.']::TEXT[], ARRAY['(harder) Goal moves faster', '(harder) Require a pass between partners before scoring', '(easier) Goal moves slowly']::TEXT[], '', 'library', CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Drill" ("id", "teamId", "name", "slug", "category", "focusAreas", "defaultMinutes", "minMinutes", "maxMinutes", "minPlayers", "maxPlayers", "equipment", "setup", "instructions", "coachingPoints", "progressions", "ageNotes", "scope", "updatedAt") VALUES ('lib-goal-to-goal-striking', NULL, 'Goal to Goal Striking', 'goal-to-goal-striking', 'technical', ARRAY['shooting', 'passing']::TEXT[], 6, 4, 8, 4, 12, ARRAY['One ball per pair', 'Cones (for goals)']::TEXT[], 'Pair players. Each player builds a small cone goal about 5-7 steps wide; partners stand about 10-20 yards apart, each defending their own goal.', 'Taking turns, players strike the ball in no more than two touches to try to score through their partner''s goal. The partner then takes their turn from where the ball ends up. Players keep a running score.', ARRAY['Laces through the middle of the ball.', 'Head steady, eyes on the ball.', 'Plant foot beside the ball.']::TEXT[], ARRAY['(harder) Move goals farther apart', '(harder) One-touch strikes', '(easier) Move closer']::TEXT[], '', 'library', CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Drill" ("id", "teamId", "name", "slug", "category", "focusAreas", "defaultMinutes", "minMinutes", "maxMinutes", "minPlayers", "maxPlayers", "equipment", "setup", "instructions", "coachingPoints", "progressions", "ageNotes", "scope", "updatedAt") VALUES ('lib-1v1-to-end-lines', NULL, '1v1 to End Lines', '1v1-to-end-lines', 'small_sided_game', ARRAY['dribbling', 'defending']::TEXT[], 6, 4, 8, 4, 12, ARRAY['Balls', 'Cones']::TEXT[], 'Divide a 20x25-yard grid into two halves. Two lines of players stand at opposite ends, one line with balls.', 'On the coach''s command a player from each line enters for a 1v1. The attacker scores by dribbling under control across the opponent''s end line; if the defender wins the ball they try to score across the other line. The round ends on a score or the ball going out, then two new players go and players switch lines.', ARRAY['Attack the space at speed.', 'Fake then go.', 'Defender stay balanced.']::TEXT[], ARRAY['(harder) Narrow the grid', '(harder) Start with a pass from the defender', '(easier) Widen the grid']::TEXT[], '', 'library', CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Drill" ("id", "teamId", "name", "slug", "category", "focusAreas", "defaultMinutes", "minMinutes", "maxMinutes", "minPlayers", "maxPlayers", "equipment", "setup", "instructions", "coachingPoints", "progressions", "ageNotes", "scope", "updatedAt") VALUES ('lib-1v1-to-cross-goals', NULL, '1v1 to Cross Goals', '1v1-to-cross-goals', 'small_sided_game', ARRAY['dribbling', 'defending', 'shooting']::TEXT[], 6, 4, 8, 4, 12, ARRAY['Balls', 'Cones (for four goals)']::TEXT[], 'In a 10x15-yard grid, place a 2-yard cone goal on each of the four sides. Split players into two groups at opposite ends.', 'One attacker starts with a ball and tries to score by dribbling through either of the two far goals; the defender protects the two goals nearest them and, if they win the ball, attacks the opposite goals. The round ends on a score or the ball out; two new players enter.', ARRAY['Pick the open goal.', 'Change direction to unbalance them.', 'Burst through.']::TEXT[], ARRAY['(harder) Shrink the grid', '(harder) Add a second attacker for 2v1', '(easier) Widen the goals']::TEXT[], '', 'library', CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Drill" ("id", "teamId", "name", "slug", "category", "focusAreas", "defaultMinutes", "minMinutes", "maxMinutes", "minPlayers", "maxPlayers", "equipment", "setup", "instructions", "coachingPoints", "progressions", "ageNotes", "scope", "updatedAt") VALUES ('lib-1v1-arrival-duel', NULL, '1v1 Arrival Duel', '1v1-arrival-duel', 'small_sided_game', ARRAY['dribbling', 'first_touch', 'shooting']::TEXT[], 5, 4, 8, 4, 12, ARRAY['Balls', 'Cones', 'Two mini goals']::TEXT[], 'Mark a square sized to the players with a mini goal in two opposite corners. Two players stand in the square.', 'One player passes the ball to the other; the receiver takes a touch, tries to get around the opponent and score in either mini goal, while the passer becomes the defender. Play the point out, then the next pair goes.', ARRAY['Good first touch to turn.', 'Attack the goal they leave open.', 'Get around them, then finish.']::TEXT[], ARRAY['(harder) Add a second oncoming defender for 1v2', '(harder) Smaller square', '(easier) Larger square']::TEXT[], '', 'library', CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Drill" ("id", "teamId", "name", "slug", "category", "focusAreas", "defaultMinutes", "minMinutes", "maxMinutes", "minPlayers", "maxPlayers", "equipment", "setup", "instructions", "coachingPoints", "progressions", "ageNotes", "scope", "updatedAt") VALUES ('lib-2v2-to-end-zones', NULL, '2v2 to End Zones', '2v2-to-end-zones', 'small_sided_game', ARRAY['dribbling', 'passing', 'defending']::TEXT[], 6, 4, 8, 4, 12, ARRAY['Balls', 'Cones']::TEXT[], 'Divide a 20x25-yard grid into two 12x20-yard fields with a 1-yard buffer between them. Mark a 1-yard-wide end zone along each end line. Two players per team on each field.', 'Teams score by dribbling and stopping the ball under control in the opponent''s end zone; defenders may not defend inside the end zone. On a score or ball out, restart quickly. Run parallel games on both fields.', ARRAY['Spread out to make space.', 'Pass or dribble - your choice.', 'Attack the empty end zone.']::TEXT[], ARRAY['(harder) Require both players to touch the ball before scoring', '(harder) Add a scoring time limit', '(easier) Widen the end zone']::TEXT[], '', 'library', CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Drill" ("id", "teamId", "name", "slug", "category", "focusAreas", "defaultMinutes", "minMinutes", "maxMinutes", "minPlayers", "maxPlayers", "equipment", "setup", "instructions", "coachingPoints", "progressions", "ageNotes", "scope", "updatedAt") VALUES ('lib-3v3-to-end-zones', NULL, '3v3 to End Zones', '3v3-to-end-zones', 'small_sided_game', ARRAY['dribbling', 'passing', 'defending', 'spatial_awareness']::TEXT[], 7, 5, 8, 6, 12, ARRAY['Balls', 'Cones']::TEXT[], 'In a 20x25-yard grid, mark a 1-yard end zone along each end line. Two teams of three.', 'Teams score by dribbling and stopping the ball under control in the opponent''s end zone; defenders may not enter the end zone. Restart quickly after a score or ball out.', ARRAY['Use the width.', 'Look up before you dribble.', 'Help the player on the ball.']::TEXT[], ARRAY['(harder) Add a scoring time limit', '(harder) Require a pass before scoring', '(easier) Widen the end zone']::TEXT[], '', 'library', CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Drill" ("id", "teamId", "name", "slug", "category", "focusAreas", "defaultMinutes", "minMinutes", "maxMinutes", "minPlayers", "maxPlayers", "equipment", "setup", "instructions", "coachingPoints", "progressions", "ageNotes", "scope", "updatedAt") VALUES ('lib-2v1-to-goal', NULL, '2v1 to Goal', '2v1-to-goal', 'small_sided_game', ARRAY['passing', 'dribbling', 'defending']::TEXT[], 6, 4, 8, 6, 12, ARRAY['Balls', 'Cones', 'Small goals or end zone']::TEXT[], 'Mark a 15x20-yard grid. Split players into three lines - two attacking lines and one defending line; the coach has the balls at the side.', 'The coach passes a ball to one attacking line and the first player from each of the three lines enters for a 2v1. The two attackers try to get the ball over the far end line under control for 1 point; if the defender wins it and scores back, the defender earns 2 points. On a score or ball out, new players enter.', ARRAY['Pass to the free player.', 'One dribbles, one runs wide.', 'Defender, don''t dive in.']::TEXT[], ARRAY['(harder) Make it 3v2', '(harder) Play to small goals', '(easier) Larger grid']::TEXT[], '', 'library', CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Drill" ("id", "teamId", "name", "slug", "category", "focusAreas", "defaultMinutes", "minMinutes", "maxMinutes", "minPlayers", "maxPlayers", "equipment", "setup", "instructions", "coachingPoints", "progressions", "ageNotes", "scope", "updatedAt") VALUES ('lib-small-sided-game-to-a-target', NULL, 'Small-Sided Game to a Target', 'small-sided-game-to-a-target', 'small_sided_game', ARRAY['passing', 'first_touch', 'spatial_awareness']::TEXT[], 6, 4, 8, 6, 12, ARRAY['Balls', 'Cones']::TEXT[], 'Mark a field with an end zone at each end. Place a target player, coach or player, in each end zone. Two teams play inside.', 'Teams play 2v2 or 3v3 and score one point by passing the ball to their target player in the end zone. After a point, play restarts with the other team. Target players rotate.', ARRAY['Look for the target early.', 'Pass to feet.', 'Move to support the ball.']::TEXT[], ARRAY['(harder) Require a set number of passes before finding the target', '(harder) Target must control it', '(easier) Enlarge the field']::TEXT[], '', 'library', CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Drill" ("id", "teamId", "name", "slug", "category", "focusAreas", "defaultMinutes", "minMinutes", "maxMinutes", "minPlayers", "maxPlayers", "equipment", "setup", "instructions", "coachingPoints", "progressions", "ageNotes", "scope", "updatedAt") VALUES ('lib-end-zone-ball-race', NULL, 'End Zone Ball Race', 'end-zone-ball-race', 'small_sided_game', ARRAY['dribbling', 'passing', 'defending']::TEXT[], 6, 4, 8, 6, 12, ARRAY['Balls', 'Cones']::TEXT[], 'Mark a rectangular field with an end zone at each end. Place a ball in each end zone and start play with one game ball. Two teams of 2 to 4.', 'A team scores by dribbling the game ball into the opponent''s end zone; they then collect a ball from their own defensive end zone and attack again. Only one ball is in play at a time. The first team to move all the balls into one end zone wins the round.', ARRAY['Dribble into the space.', 'Turn away from pressure to keep it.', 'Go quickly after you score.']::TEXT[], ARRAY['(harder) Shrink the field', '(harder) Require a pass before entering the end zone', '(easier) Enlarge the field']::TEXT[], '', 'library', CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Drill" ("id", "teamId", "name", "slug", "category", "focusAreas", "defaultMinutes", "minMinutes", "maxMinutes", "minPlayers", "maxPlayers", "equipment", "setup", "instructions", "coachingPoints", "progressions", "ageNotes", "scope", "updatedAt") VALUES ('lib-making-your-moves', NULL, 'Making Your Moves', 'making-your-moves', 'small_sided_game', ARRAY['dribbling', 'defending', 'passing']::TEXT[], 6, 4, 8, 4, 12, ARRAY['Balls', 'Cones', 'Two mini goals (optional)']::TEXT[], 'Mark a rectangle sized to the players with an end zone at each end; for larger groups set up several separate rectangles. Two players per team in each rectangle, each side starting in its own end zone.', 'One pair starts with the ball and attacks to move it into the opponents'' end zone for one point; the other pair defends and, if they win the ball, attacks the opposite way. After a score, restart with the other side in possession.', ARRAY['Move the ball into space.', 'Take them on 1v1.', 'Win it back and go.']::TEXT[], ARRAY['(harder) Shrink the area', '(harder) Replace end zones with mini goals to add finishing', '(easier) Enlarge the area']::TEXT[], '', 'library', CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Drill" ("id", "teamId", "name", "slug", "category", "focusAreas", "defaultMinutes", "minMinutes", "maxMinutes", "minPlayers", "maxPlayers", "equipment", "setup", "instructions", "coachingPoints", "progressions", "ageNotes", "scope", "updatedAt") VALUES ('lib-4v4-to-small-goals', NULL, '4v4 to Small Goals', '4v4-to-small-goals', 'small_sided_game', ARRAY['passing', 'dribbling', 'shooting', 'defending', 'spatial_awareness']::TEXT[], 8, 6, 8, 8, 12, ARRAY['Size-3 balls', 'Cones', 'Small goals (max 4 ft x 6 ft, no keepers)']::TEXT[], 'Mark a field about 35 yards long by 25 yards wide with a small goal at each end, no goalkeepers. For a full roster, set up two parallel fields with a 5-yard gap. Teams of four. This mirrors the official U8 matchday format under the U.S. Soccer Player Development Initiatives: 4v4, no goalkeeper, 25-35 x 15-25-yard field, size-3 ball, no offside.', 'Two teams play a normal game to the small goals. Quick restarts by dribble-in or kick-in after the ball goes out. Rotate or sub players between short rounds.', ARRAY['Spread out like a diamond.', 'Look up, then decide.', 'Everyone attacks, everyone defends.']::TEXT[], ARRAY['(harder) Add small end-zone bonus targets', '(easier) Widen goals and allow unlimited touches', '(variation) 3v3 or 3v3 plus one neutral for fewer players']::TEXT[], '', 'library', CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Drill" ("id", "teamId", "name", "slug", "category", "focusAreas", "defaultMinutes", "minMinutes", "maxMinutes", "minPlayers", "maxPlayers", "equipment", "setup", "instructions", "coachingPoints", "progressions", "ageNotes", "scope", "updatedAt") VALUES ('lib-doctor-doctor', NULL, 'Doctor Doctor', 'doctor-doctor', 'fun_finisher', ARRAY['passing', 'dribbling', 'fitness_disguised']::TEXT[], 5, 4, 7, 8, 12, ARRAY['One ball per player', 'Cones (for two hospital corners)']::TEXT[], 'Mark a 15x20-yard grid with a small hospital box near each end. Divide into two teams; each team picks one player as the doctor, who has no ball. All other players have a ball.', 'Teams try to freeze opponents by striking their ball or hitting them below the knee with a passed ball. A frozen player holds their ball above their head and calls "doctor, doctor" until their team''s doctor runs out and touches them to unfreeze them. The doctor is safe inside a hospital but can be frozen when out. The round ends when a team''s doctor is frozen, then reset.', ARRAY['Pass low and accurate.', 'Protect the doctor.', 'Aim before you strike.']::TEXT[], ARRAY['(harder) Allow only one doctor per team', '(harder) Shrink the grid', '(easier) Larger hospitals']::TEXT[], '', 'library', CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Drill" ("id", "teamId", "name", "slug", "category", "focusAreas", "defaultMinutes", "minMinutes", "maxMinutes", "minPlayers", "maxPlayers", "equipment", "setup", "instructions", "coachingPoints", "progressions", "ageNotes", "scope", "updatedAt") VALUES ('lib-capture-the-balls', NULL, 'Capture the Balls', 'capture-the-balls', 'fun_finisher', ARRAY['dribbling', 'passing', 'defending']::TEXT[], 5, 4, 7, 6, 12, ARRAY['Many balls', 'Cones (for corner home bases)']::TEXT[], 'Mark a grid with a home base in each corner for each team. Pile the balls in the middle; players start inside their own home base.', 'On the coach''s command, players run out and each dribble or pass one ball at a time back to their home base. Players may also steal balls from opponents'' home bases. When the coach calls time, each team counts the balls in their base; most balls wins. Reset the pile and play again.', ARRAY['Grab one, bring it home.', 'Keep your head up for stealers.', 'Protect your base.']::TEXT[], ARRAY['(harder) Require dribbling only', '(harder) Allow one defender per base', '(easier) More balls']::TEXT[], '', 'library', CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Drill" ("id", "teamId", "name", "slug", "category", "focusAreas", "defaultMinutes", "minMinutes", "maxMinutes", "minPlayers", "maxPlayers", "equipment", "setup", "instructions", "coachingPoints", "progressions", "ageNotes", "scope", "updatedAt") VALUES ('lib-catching-robbers', NULL, 'Catching Robbers', 'catching-robbers', 'fun_finisher', ARRAY['passing', 'dribbling', 'fitness_disguised']::TEXT[], 5, 4, 7, 6, 12, ARRAY['Balls', 'Cones']::TEXT[], 'Mark a 20x25-yard grid. Spread balls around the perimeter. Two players start with a ball as cops; the rest have no ball and run inside the grid.', 'On the coach''s command, the cops try to hit other players below the knee by passing their ball at them. A player who is hit collects a ball from the perimeter and becomes a cop. Play continues until most players are cops, then reset.', ARRAY['Dribble close before you pass.', 'Aim low.', 'Spread out to trap them.']::TEXT[], ARRAY['(harder) Start with one cop', '(harder) Shrink the grid', '(easier) Start with more cops']::TEXT[], '', 'library', CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;
INSERT INTO "Drill" ("id", "teamId", "name", "slug", "category", "focusAreas", "defaultMinutes", "minMinutes", "maxMinutes", "minPlayers", "maxPlayers", "equipment", "setup", "instructions", "coachingPoints", "progressions", "ageNotes", "scope", "updatedAt") VALUES ('lib-clean-your-backyard', NULL, 'Clean Your Backyard', 'clean-your-backyard', 'fun_finisher', ARRAY['shooting', 'passing', 'fitness_disguised']::TEXT[], 5, 4, 7, 6, 12, ARRAY['Many balls', 'Cones', 'Goals (optional)']::TEXT[], 'Split a 20x25-yard grid into two halves with a 4-6-yard no-entry buffer zone in the middle; place two or three cone goals along each end. Divide into two teams, one per half, with the balls shared out between them.', 'On "go," both teams strike balls out of their own half, either into the other team''s goals or across into the other half, while keeping fewer balls in their own half. Players immediately fetch another ball in their half and strike again. No one enters the buffer zone except to retrieve a stopped ball. On "stop," the team with fewer balls in its half wins the round.', ARRAY['Strike low and hard.', 'Keep clearing your yard.', 'Grab the next ball fast.']::TEXT[], ARRAY['(harder) Score only through the goals', '(harder) Weaker foot only', '(easier) More balls and wider goals']::TEXT[], '', 'library', CURRENT_TIMESTAMP) ON CONFLICT ("id") DO NOTHING;

-- Give every existing team its own editable/deletable copy of each new
-- template, matching the pattern used when the original 20 were detached
-- from the shared library (see detach_drills_per_team). Skips a team that
-- somehow already has a drill with this slug (e.g. re-running after a
-- partial deploy).
INSERT INTO "Drill" ("id", "teamId", "name", "slug", "category", "focusAreas", "defaultMinutes", "minMinutes", "maxMinutes", "minPlayers", "maxPlayers", "equipment", "setup", "instructions", "coachingPoints", "progressions", "ageNotes", "scope", "archived", "updatedAt")
SELECT
  gen_random_uuid()::text,
  t.id,
  d.name,
  d.slug,
  d.category,
  d."focusAreas",
  d."defaultMinutes",
  d."minMinutes",
  d."maxMinutes",
  d."minPlayers",
  d."maxPlayers",
  d.equipment,
  d.setup,
  d.instructions,
  d."coachingPoints",
  d.progressions,
  d."ageNotes",
  'team',
  false,
  CURRENT_TIMESTAMP
FROM "Team" t
CROSS JOIN "Drill" d
WHERE d.scope = 'library'
  AND d.id LIKE 'lib-%'
  AND NOT EXISTS (
    SELECT 1 FROM "Drill" existing
    WHERE existing."teamId" = t.id AND existing.slug = d.slug AND existing.slug != ''
  );
